// B7: every call says which contract the nodes were built for (contract.ts, generated by `manage.py contract --ts`
// from the server's definitions; a Django test says when it is stale), and a server's mismatch warning becomes
// one hint in the node's output, not an error.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { Bpmn8nClient } = require('../dist/nodes/shared/Bpmn8nClient.js');
const { CONTRACT_VERSION, HEADERS } = require('../dist/nodes/shared/contract.js');

function ctx(replyHeaders = {}) {
	const sent = [];
	const hints = [];
	return {
		sent,
		hints,
		getCredentials: async () => ({ baseUrl: 'http://web:8000/' }),
		getNode: () => ({ name: 'Book Slot', id: 'n1' }),
		getWorkflow: () => ({ id: 'w1', name: 'Booking' }),
		getExecutionId: () => '42',
		getWorkflowDataProxy: () => ({ $runIndex: 0 }),
		addExecutionHints: (...h) => hints.push(...h),
		helpers: {
			httpRequestWithAuthentication: async (_name, options) => {
				sent.push(options);
				return { statusCode: 200, body: { result: {} }, headers: replyHeaders };
			},
		},
	};
}

test('every call carries the contract version and the run identity', async () => {
	const c = ctx();
	await new Bpmn8nClient(c).post('/api/tasks/book_slot/run', { fields: {} }, 0);
	const { headers, url } = c.sent[0];
	assert.equal(url, 'http://web:8000/api/tasks/book_slot/run');
	assert.equal(headers[HEADERS.contract], CONTRACT_VERSION);
	assert.match(CONTRACT_VERSION, /^1\.[0-9a-f]{8}$/);
	assert.equal(headers['X-Bpmn8n-Case'], 'w1%3A42'); // URI-encoded
	assert.deepEqual(Object.keys(headers).sort(), ['case', 'process', 'activity', 'node', 'item', 'run', 'contract'].map((k) => HEADERS[k]).sort());
	assert.deepEqual(c.hints, []);
});

test("a server that speaks another contract answers with a warning, shown once", async () => {
	const c = ctx({ 'x-bpmn8n-warning': 'the bpmn8n nodes speak contract 1.0, this server 1.1' });
	const client = new Bpmn8nClient(c);
	const reply = await client.post('/api/tasks/book_slot/run', {});
	await client.request('GET', '/api/openapi.json');
	assert.deepEqual(reply, { result: {} }); // the call still succeeds
	assert.equal(c.hints.length, 1);
	assert.equal(c.hints[0].type, 'warning');
	assert.match(c.hints[0].message, /this server 1\.1/);
});
